14	};
15	
16	export type ScenarioResult = {
17	  results: { premium: number }[];
18	};
19	
20	const PROCESSING_FEE = 5;
21	
22	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
23	
24	const BASE_PREMIUMS: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	// Every percentage modifier is a delta computed against an *unmodified* base
34	// and summed with the others — modifiers never compound. Policy-wide ones use
35	// the policy base, item-specific ones the affected item's own base premium.
36	//
37	// Percentages stay in integer percent points: multiply first, divide by 100
38	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
39	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
40	const percentOf = (amount: number, percent: number): number =>
41	  (amount * percent) / 100;
42	
43	const BLOCK_SIZE = 3;
44	const BLOCK_BASE_PREMIUM = 60;
45	
46	const countByType = (items: Item[]): Map<string, number> => {
47	  const counts = new Map<string, number>();
48	
49	  for (const item of items) {
50	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
51	  }
52	
53	  return counts;
54	};
55	
56	const baseOfGroup = (type: string, count: number): number =>
57	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
58	
59	const policyBaseOf = (items: Item[]): number =>
60	  [...countByType(items)].reduce(
61	    (total, [type, count]) => total + baseOfGroup(type, count),
62	    0,
63	  );
64	
65	// A modifier rule: when `applies` holds for the subject, `percent` percent of
66	// the relevant base premium is added. A negative percent is a discount. Every
67	// rule whose predicate holds contributes; the deltas are summed, never
68	// compounded.
69	type ModifierRule<Subject> = {
70	  applies: (subject: Subject) => boolean;
71	  percent: number;
72	};
73	
74	const sumApplicablePercents = <Subject>(
75	  rules: ModifierRule<Subject>[],
76	  subject: Subject,
77	): number =>
78	  rules.reduce(
79	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
80	    0,
81	  );
82	
83	// Policy-wide modifiers: each is a percentage of the policy base premium.
84	const LOYALTY_YEARS_THRESHOLD = 2;
85	const LOYALTY_DISCOUNT_PERCENT = -20;
86	
87	const POLICY_MODIFIER_RULES: ModifierRule<Customer>[] = [
88	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
89	  {
90	    applies: (customer) => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
91	    percent: LOYALTY_DISCOUNT_PERCENT,
92	  },
93	];
94	
95	const policyModifiersOf = (policyBase: number, customer: Customer): number =>
96	  percentOf(policyBase, sumApplicablePercents(POLICY_MODIFIER_RULES, customer));
97	
98	// Item-specific modifiers: each is a percentage of the affected item's own
99	// base premium.
100	const CURSE_SURCHARGE_PERCENT = 50;
101	const HIGH_ENCHANTMENT_THRESHOLD = 5;
102	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
103	
104	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
105	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
106	  {
107	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
108	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
109	  },
110	];
111	
112	const itemModifiersOf = (item: Item): number =>
113	  percentOf(
114	    BASE_PREMIUMS[item.type],
115	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
116	  );
117	
118	const quote = (items: Item[], customer: Customer): number => {
119	  const policyBase = policyBaseOf(items);
120	  const modifiers =
121	    policyModifiersOf(policyBase, customer) +
122	    items.reduce((total, item) => total + itemModifiersOf(item), 0);
123	
124	  // Rounding is in the MHPCO's favour: premiums round up.
125	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
126	};
127	
128	export const runScenario = (scenario: Scenario): ScenarioResult => ({
129	  results: scenario.steps.map((step) => ({
130	    premium: quote(step.items, scenario.customer),
131	  })),
132	});
