// Policy-wide modifiers: each is a percentage of the policy base premium.
//
// Their subject is the *policy* — the circumstances under which this quote is
// issued — not the customer alone. Today those circumstances are just who is
// asking; rules that also depend on where the quote sits in the scenario read
// the field they need off the same subject.
type Policy = {
  customer: Customer;
};

const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_PERCENT = -20;

const POLICY_MODIFIER_RULES: ModifierRule<Policy>[] = [
  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
  {
    applies: ({ customer }) =>
      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
    percent: LOYALTY_DISCOUNT_PERCENT,
  },
];

const policyModifierDelta = (policyBase: number, policy: Policy): number =>
  percentOf(policyBase, sumApplicablePercents(POLICY_MODIFIER_RULES, policy));

